from solution import jsonrpc_error

def test_jsonrpc_error_basic():
    result = jsonrpc_error('1', 400, 'Bad Request')
    assert result == {'jsonrpc': '2.0', 'id': '1', 'error': {'code': 400, 'message': 'Bad Request'}}

def test_jsonrpc_error_with_data():
    result = jsonrpc_error(None, 500, 'Internal Error', {'detail': 'Something went wrong'})
    assert result == {'jsonrpc': '2.0', 'id': None, 'error': {'code': 500, 'message': 'Internal Error', 'data': {'detail': 'Something went wrong'}}}

def test_jsonrpc_error_integer_id():
    result = jsonrpc_error(12345, -32700, 'Parse Error')
    assert result == {'jsonrpc': '2.0', 'id': 12345, 'error': {'code': -32700, 'message': 'Parse Error'}}

def test_jsonrpc_error_none_request_id():
    result = jsonrpc_error(None, None, 'Null Error', None)
    assert result == {'jsonrpc': '2.0', 'id': None, 'error': {'code': None, 'message': 'Null Error'}}

def test_jsonrpc_error_empty_string_id():
    result = jsonrpc_error('', 0, 'Zero Code')
    assert result == {'jsonrpc': '2.0', 'id': '', 'error': {'code': 0, 'message': 'Zero Code'}}

def test_jsonrpc_error_no_data_value():
    result = jsonrpc_error('test', 404, 'Not Found')
    assert 'data' not in result['error']

def test_jsonrpc_error_complex_data():
    result = jsonrpc_error(42, 418, 'Tea Server', {'nested': {'deep': {'value': 123}}})
    assert result['error']['data'] == {'nested': {'deep': {'value': 123}}}

