from solution import export_cookies_from_page

def test_empty_page_returns_empty_list():
    assert export_cookies_from_page(None) == []

def test_page_with_none_cookies_returns_empty_list():

    class MockPage:
        cookies = None
    page = MockPage()
    assert export_cookies_from_page(page) == []

def test_page_returns_list_of_dicts():

    class MockPage:

        def cookies(self, all_domains=True, all_info=False):
            return [{'name': 'session', 'value': 'abc'}]
    page = MockPage()
    result = export_cookies_from_page(page)
    assert result == [{'name': 'session', 'value': 'abc'}]

def test_page_returns_list_of_mixed_types_filters_out_non_dicts():

    class MockPage:

        def cookies(self, all_domains=True, all_info=False):
            return [{'name': 'session', 'value': 'abc'}, 'not a dict', None]
    page = MockPage()
    result = export_cookies_from_page(page)
    assert result == [{'name': 'session', 'value': 'abc'}]

def test_page_returns_none_on_first_try_catches_type_error():

    class MockPage:

        def cookies(self, all_domains=True, all_info=False):
            raise TypeError('unsupported')

        def cookies(self, all_domains=True):
            return [{'name': 'session', 'value': 'abc'}]
    page = MockPage()
    result = export_cookies_from_page(page)
    assert result == [{'name': 'session', 'value': 'abc'}]

def test_fallback_to_browser_cookies():

    class MockPage:

        @property
        def browser(self):

            class MockBrowser:

                def cookies(self):
                    return [{'name': 'browser_cookie', 'value': 'xyz'}]
            return MockBrowser()
    page = MockPage()
    result = export_cookies_from_page(page)
    assert result == [{'name': 'browser_cookie', 'value': 'xyz'}]

def test_no_cookies_returns_empty_list():

    class MockPage:

        def cookies(self, all_domains=True, all_info=False):
            raise TypeError('unsupported')

        @property
        def browser(self):
            raise RuntimeError('browser error')
    page = MockPage()
    result = export_cookies_from_page(page)
    assert result == []

